const tabId = 2136412417;
const deals = await browserjs(tabId, () => {
  const simWrap = document.querySelector('.sim-wrap');
  if (!simWrap) return { error: "No sim-wrap found" };

  // Let's inspect the deal elements inside simWrap
  const dealCards = Array.from(simWrap.querySelectorAll('.sim-item, .deal-item, .listing, .result-item, .sim-box, .deal, div[data-deal]'));

  // If no standard class, let's grab all text blocks or inspect children
  const children = Array.from(simWrap.children).map(c => ({
    tagName: c.tagName,
    className: c.className,
    text: c.innerText.slice(0, 300)
  }));

  return {
    dealCardsCount: dealCards.length,
    childrenCount: simWrap.children.length,
    children: children.slice(0, 10),
    fullTextSnippet: simWrap.innerText.slice(0, 3000)
  };
});
console.log(JSON.stringify(deals, null, 2));

