const tabId = 2136412417;
const cardsData = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll('.content-card.simo_card'));
  return cards.map(c => {
    const text = c.innerText;
    // Extract key details
    const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
    const providerMatch = text.match(/Get deal via ([^\*\n]+)/i) || text.match(/uses ([^\)]+)\)/i);
    const dataMatch = text.match(/(\d+GB|Unlimited)\b/i);
    const minsMatch = text.match(/Mins\/texts\s*\n?\s*([^\n]+)/i);
    const equivCostMatch = text.match(/Equivalent cost[^:]*:\s*\n?\s*(£[\d\.]+)/i);
    const monthlyMatch = text.match(/(£[\d\.]+\/mth)/gi);

    return {
      fullText: text,
      provider: providerMatch ? providerMatch[1].trim() : null,
      data: dataMatch ? dataMatch[1] : null,
      minsTexts: minsMatch ? minsMatch[1] : null,
      equivCost: equivCostMatch ? equivCostMatch[1] : null,
      monthlyCosts: monthlyMatch
    };
  });
});
console.log(JSON.stringify(cardsData.slice(0, 10), null, 2));

